// Templates use only documented universal PLC functions. Physical outputs are assigned separately.
function exampleBuilder(title){
 const p=blank();p.title=title;const timers=[],outputsInfo=[];
 const b=(code,values,label,note='')=>{const slot=p.nodes.filter(n=>n.kind==='block').length+1;p.nodes.push({id:'b'+slot,kind:'block',slot,code,values,label,note,x:600+(slot-1)%4*600,y:210+Math.floor((slot-1)/4)*560});return 255+slot;};
 const c=(value,label)=>{const resource=p.nodes.filter(n=>n.kind==='constant').length;p.nodes.push({id:'k'+resource,kind:'constant',resource,values:{value},label,note:'Задане значення прикладу',x:50,y:300+resource*190});return 320+resource;};
 const output=(pch,name)=>outputsInfo.push({pch,name});
 function ton(signal,ms,label){
  const first=p.nodes.filter(n=>n.kind==='block').length+1;
  const add=b(8,{A:255+first+2,B:1},label+': +1 цикл');
  const cap=b(7,{A:add,B:0,C:1},label+': обмеження');
  const count=b(9,{A:0,B:cap,C:signal},label+': лічба / скидання','Коли умова зникає, накопичення циклів скидається.');
  const done=b(12,{A:count,B:0,C:1},label+': час минув');
  timers.push({cap,count,done,ms});return done;
 }
 function finish(description,inputs,notes=[]){
  syncSlots(p);const tick=p.cycle*.2;
  for(const timer of timers){const ticks=Math.ceil(timer.ms/tick);if(ticks>32000)throw Error('Час поза діапазоном прикладу');p.nodes.find(n=>255+n.slot===timer.cap).values.C=ticks;p.nodes.find(n=>255+n.slot===timer.done).values.C=ticks;p.nodes.find(n=>255+n.slot===timer.count).note+=' Для початкової схеми: '+ticks+' циклів × '+tick.toFixed(1)+' мс ≈ '+(ticks*tick/1000).toFixed(3)+' с. Після зміни кількості блоків перерахуйте поріг.';}
  for(const target of [...p.nodes])for(const field of fields(target))if(field.type==='pch'){
   const pch=target.values[field.key];if(pch===0||pch===7)continue;
   let source=p.nodes.find(n=>!isReference(n)&&outputs(n).includes(pch));
   if(!source){source={id:'src'+pch,kind:'source',pch,values:{},label:PCH[pch],note:inputs.find(i=>i.pch===pch)?.name||PCH[pch],x:40,y:100};p.nodes.push(source);}
   connectProjectInput(p,target.id,field.key,pch,source.id);
  }
  const summary=description+'\n\nВходи:\n'+inputs.map(i=>'PCH'+i.pch+' – '+i.name).join('\n')+'\n\nВиходи:\n'+outputsInfo.map(i=>'PCH'+i.pch+' – '+i.name).join('\n')+'\n\n'+notes.join('\n');
  p.nodes.push({id:'example_info',kind:'comment',values:{},label:title,note:summary,width:470,height:180,x:30,y:25});
  layoutPlcExample(p);
  syncSlots(p);return {project:p,description,inputs,outputs:outputsInfo,notes,tick};
 }
 return {p,b,c,ton,output,finish};
}
